import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {digest} from '../live-paper/model.mjs';
import {atomicJson,payloadHash} from '../execution/ledger.mjs';
import {exportProbabilityOpening,probabilityContinuationBundle} from '../live-paper/probability-continuation.mjs';
import {openProbabilityReceipt} from '../live-paper/probability-receipt-host-v2.mjs';
const runtimeDir=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),sha=b=>createHash('sha256').update(b).digest('hex');
const marker=JSON.parse(fs.readFileSync(path.join(runtimeDir,'COLLECTOR_STOP')));
if(marker.source!=='probability-owned-risk-20261004')throw Error('Engineering marker provenance');
for(const file of ['STOP',path.join(runtimeDir,'STOP'),path.join(runtimeDir,'..','bot.lock')])if(fs.existsSync(file))throw Error('Human STOP or collector ownership');
if(JSON.parse(fs.readFileSync(path.join(runtimeDir,'competition-activation.json'))).enabled!==false)throw Error('Contest activation');
const active=JSON.parse(fs.readFileSync(path.join(runtimeDir,'probability-receipt-active.json'))),oldDir=path.join(runtimeDir,'probability-receipt-cohorts',active.cohort),oldStats=JSON.parse(fs.readFileSync(path.join(oldDir,'stats.json')));
if(active.cohort!=='source-probability-20261003-v1'||oldStats.failed||!oldStats.sourceClosed)throw Error('Predecessor has not consumed closed source');
const opening=exportProbabilityOpening({runtimeDir,cohort:active.cohort});
if(digest(opening.priorBank)!==active.bankHash||opening.journalHash!==oldStats.journalHash||digest(opening.state)!==oldStats.stateHash)throw Error('Published predecessor frontier');
const cohort='source-probability-owned-risk-20261004-v2',w=openProbabilityReceipt({runtimeDir,cohort,initialize:true,bundle:probabilityContinuationBundle(opening)}),bank=w.bank,status=w.status();w.close();
const indexFile=path.join(runtimeDir,'frozen-code','index.json'),index=JSON.parse(fs.readFileSync(indexFile));
const previous=index.banks[active.bankHash];if(!previous)throw Error('Original frozen source missing');
const manifest=JSON.parse(fs.readFileSync(path.join(runtimeDir,'frozen-code',previous.snapshot,'manifest.json'))),files={};
const names=[...new Set([...Object.keys(manifest.files),'live-paper/probability-receipt-v2.mjs','live-paper/probability-receipt-host-v2.mjs','live-paper/probability-receipt-observe-v2.mjs','live-paper/probability-continuation.mjs'])].sort();
for(const name of names)files[name]=sha(fs.readFileSync(name));
const snapshot=payloadHash(files),root=path.join(runtimeDir,'frozen-code',snapshot);
if(fs.existsSync(root))throw Error('Snapshot collision; inspect');fs.mkdirSync(root,{recursive:true,mode:0o700});
for(const name of names){const file=path.join(root,name);fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o700});fs.writeFileSync(file,fs.readFileSync(name),{flag:'wx',mode:0o600});}
atomicJson(path.join(root,'manifest.json'),{schemaVersion:1,files});index.banks[digest(bank)]={snapshot};atomicJson(indexFile,index);
atomicJson(path.join(w.dir,'stats.json'),status);
const preserved={at:new Date().toISOString(),cohort:active.cohort,bankHash:active.bankHash,bankFileHash:opening.priorBankFileHash,journalBytes:opening.journalBytes,journalFileHash:opening.journalFileHash,journalSequence:opening.journalSequence,journalHash:opening.journalHash,stateHash:digest(opening.state)};
const wallets=Object.fromEntries(Object.entries(status.wallets).map(([latency,s])=>[latency,{cash:s.cash,realizedPnl:s.realizedPnl,fees:s.fees,fills:s.fills,closedTrades:s.closedTrades,positions:s.positions.map(p=>({instrument:p.instrument,quantity:p.quantity,cost:p.cost})),liquidationPnl:s.liquidationPnl}]));
atomicJson(path.join(oldDir,'preserved-owned-risk-20261004.json'),preserved);
atomicJson('data/probability-owned-risk-preservation-20261004.json',preserved);
atomicJson('data/probability-owned-risk-deployment-20261004.json',{at:bank.cutoff,cohort,bankHash:digest(bank),accountingContinuation:bank.accountingContinuation,frozenSourceSnapshot:snapshot,frozenFiles:names.length,wallets,competitionOrders:0,additionalPersistentProcesses:0,additionalReadSlots:0,profitabilityEstablished:false});
console.log(JSON.stringify({cohort,bankHash:digest(bank),sourceClosed:status.sourceClosed,wallets,competitionOrders:0}));
